class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        operations = 0
        i = 1
        n = len(word)
        while i < n:
            if abs(ord(word[i]) - ord(word[i-1])) <= 1:
                operations += 1
                i += 2  # Skip the next character to avoid overlapping checks
            else:
                i += 1
        return operations
